package com.kuaima.app.admin.service;

import java.math.BigDecimal;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import org.springframework.data.domain.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;
import com.alibaba.fastjson2.JSON;
import com.kuaima.app.domain.coupon.entity.Coupon;
import com.kuaima.app.domain.coupon.entity.UserCoupon;
import com.kuaima.app.domain.coupon.repository.CouponRepository;
import com.kuaima.app.domain.coupon.repository.UserCouponRepository;
import com.kuaima.app.domain.user.entity.User;
import com.kuaima.app.domain.user.repository.UserRepository;
import com.kuaima.app.domain.user.constant.UserRole;
import jakarta.persistence.EntityNotFoundException;

@Service
public class AdminCouponService {
  private static final ZoneId ZONE=ZoneId.of("Asia/Shanghai");
  private static final Set<String> TYPES=Set.of("满减券","折扣券","立减券");
  private static final Set<String> TARGETS=Set.of("老板","零工","全部用户");
  private final CouponRepository coupons; private final UserCouponRepository claims; private final UserRepository users;
  public AdminCouponService(CouponRepository c,UserCouponRepository uc,UserRepository u){coupons=c;claims=uc;users=u;}
  @Transactional public Page<Coupon> list(String status,String type,String target,String keyword,Pageable p){syncStatuses();return coupons.search(blank(status),blank(type),blank(target),blank(keyword),p);}
  public Map<String,Object> stats(){List<Coupon> all=coupons.findAll().stream().filter(c->!Boolean.TRUE.equals(c.getDeleted())).peek(this::refreshStatus).toList();long ongoing=all.stream().filter(c->"进行中".equals(c.getStatus())).count(),upcoming=all.stream().filter(c->"未开始".equals(c.getStatus())).count(),ended=all.stream().filter(c->"已结束".equals(c.getStatus())).count(),used=all.stream().mapToLong(c->claims.countByCouponIdAndStatus(c.getId(),"USED")).sum(),claimed=all.stream().mapToLong(c->claims.countByCouponId(c.getId())).sum();return Map.of("ongoing",ongoing,"upcoming",upcoming,"ended",ended,"used",used,"usedRate",claimed==0?0:Math.round(used*1000.0/claimed)/10.0); }
  @Transactional public Coupon create(Map<String,Object> body){ Coupon c=new Coupon(); apply(c,body,true); c.setCouponNo("CP"+LocalDateTime.now(ZONE).format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss"))+UUID.randomUUID().toString().substring(0,6).toUpperCase()); c.setClaimed(0);c.setUsed(0);c.setDeleted(false);c.setStopped(false);c=coupons.saveAndFlush(c);if(c.getGrantStart()!=null&&!c.getGrantStart().isAfter(LocalDateTime.now(ZONE)))distribute(c);return c; }
  @Transactional public void distributeDue(Long couponId){Coupon c=coupons.findByIdForUpdate(couponId).filter(x->!Boolean.TRUE.equals(x.getDeleted())&&!Boolean.TRUE.equals(x.getStopped())).orElse(null);if(c==null||c.getGrantStart()==null||c.getGrantStart().isAfter(LocalDateTime.now(ZONE))||c.getTotal()==null||c.getTotal()<=0)return;distribute(c);}
  private void distribute(Coupon c){List<Long> targetIds=targetUserIds(c);if("custom".equals(c.getScope())&&targetIds.size()>n(c.getTotal()))throw new IllegalArgumentException("发放总量不能小于指定用户数量");Set<Long> existing=new HashSet<>(claims.findUserIdsByCouponId(c.getId()));int remaining=Math.max(0,n(c.getTotal())-existing.size());List<UserCoupon> records=new ArrayList<>();for(Long userId:targetIds){if(remaining<=0)break;if(existing.contains(userId))continue;UserCoupon uc=new UserCoupon();uc.setUserId(userId);uc.setCouponId(c.getId());uc.setStatus("UNUSED");uc.setExpireAt(expireAt(c));records.add(uc);remaining--;}if(!records.isEmpty())claims.saveAll(records);c.setClaimed(existing.size()+records.size());coupons.save(c);}
  private List<Long> targetUserIds(Coupon c){if("custom".equals(c.getScope()))return JSON.parseArray(c.getAssignUsers(),Long.class).stream().distinct().sorted().toList();return users.findAll().stream().filter(u->"全部用户".equals(c.getTarget())||("老板".equals(c.getTarget())&&UserRole.BOSS.equals(u.getRole()))||("零工".equals(c.getTarget())&&UserRole.USER.equals(u.getRole()))).map(User::getId).filter(Objects::nonNull).distinct().sorted().toList();}
  private java.sql.Date expireAt(Coupon c){LocalDate expiry="after".equals(c.getValidMode())?LocalDate.now(ZONE).plusDays(n(c.getValidDays())):c.getValidEnd()==null?null:c.getValidEnd().toLocalDate();return expiry==null?null:java.sql.Date.valueOf(expiry);}
  @Transactional public Coupon update(Long id,Map<String,Object> body){Coupon c=get(id);refreshStatus(c);if("已结束".equals(c.getStatus()))throw new IllegalArgumentException("已结束优惠券不可编辑");int claimed=(int)claims.countByCouponId(id),used=(int)claims.countByCouponIdAndStatus(id,"USED");apply(c,body,false);if(c.getTotal()<claimed)throw new IllegalArgumentException("发放总量不能小于已领取数量");c.setClaimed(claimed);c.setUsed(used);return coupons.save(c);}
  @Transactional public Coupon toggle(Long id){ Coupon c=get(id);refreshStatus(c);if("已结束".equals(c.getStatus()))throw new IllegalArgumentException("已结束优惠券不可启停");c.setStopped(!Boolean.TRUE.equals(c.getStopped()));refreshStatus(c);return coupons.save(c); }
  @Transactional public void delete(Long id){ Coupon c=get(id); if(claims.existsByCouponId(id)){c.setDeleted(true);c.setStopped(true);coupons.save(c);}else coupons.delete(c); }
  private Coupon get(Long id){return coupons.findById(id).filter(c->!Boolean.TRUE.equals(c.getDeleted())).orElseThrow(()->new EntityNotFoundException("优惠券不存在: "+id));}
  private void apply(Coupon c,Map<String,Object>b,boolean create){String name=s(b,"name");if(create&&!StringUtils.hasText(name))throw new IllegalArgumentException("优惠券名称不能为空");if(StringUtils.hasText(name)){c.setName(name.trim());c.setTitle(name.trim());}String type=s(b,"type");if(!TYPES.contains(type))throw new IllegalArgumentException("type 参数无效");c.setType(type);String target=s(b,"target");if(!TARGETS.contains(target))throw new IllegalArgumentException("target 参数无效");c.setTarget(target);String scope=s(b,"scope");if(!Set.of("all","custom").contains(scope))throw new IllegalArgumentException("scope 参数无效");c.setScope(scope);int total=i(b,"total"),limit=i(b,"limit");if(total<=0||limit<=0)throw new IllegalArgumentException("发放总量和每人限领必须大于0");List<String> ids=arr(b.get("assignUsers"));if("custom".equals(scope)){if(ids.isEmpty())throw new IllegalArgumentException("指定用户不能为空");if(total<ids.stream().distinct().count())throw new IllegalArgumentException("发放总量("+total+")不能少于指定用户数("+ids.stream().distinct().count()+")，请调整发放总量或减少指定用户");List<Long> resolved=new ArrayList<>();for(String x:ids){User u=users.findById(parseId(x)).orElseGet(()->users.findByPhone(x).stream().findFirst().orElse(null));if(u==null)throw new IllegalArgumentException("指定用户不存在: "+x);if(!"全部用户".equals(target)&&(("老板".equals(target)&&!UserRole.BOSS.equals(u.getRole()))||("零工".equals(target)&&!UserRole.USER.equals(u.getRole()))))throw new IllegalArgumentException("指定用户身份与发放对象不匹配: "+x);resolved.add(u.getId());}c.setAssignUsers(JSON.toJSONString(resolved.stream().distinct().toList()));}else c.setAssignUsers("[]");c.setTotal(total);c.setLimitPerUser(limit);String grant=s(b,"grantMode");if(!Set.of("now","timing").contains(grant))throw new IllegalArgumentException("grantMode 参数无效");c.setGrantMode(grant);c.setGrantStart("now".equals(grant)?LocalDateTime.now(ZONE):dt(b.get("grantStart")));if(c.getGrantStart()==null)throw new IllegalArgumentException("定时发放时间不能为空");String valid=s(b,"validMode");if(!Set.of("range","after").contains(valid))throw new IllegalArgumentException("validMode 参数无效");c.setValidMode(valid);c.setValidStart(dt(b.get("validStart")));c.setValidEnd(dt(b.get("validEnd")));c.setValidDays(i0(b,"validDays"));c.setDescription(s(b,"description"));if("满减券".equals(type)){BigDecimal amount=bd(b,"amount"),th=bd(b,"threshold");if(amount.signum()<=0||th.signum()<0||amount.compareTo(th)>0)throw new IllegalArgumentException("满减券金额或门槛不合法");c.setAmount(amount);c.setMinSpend(th);c.setThreshold(th);}else if("立减券".equals(type)){BigDecimal amount=bd(b,"amount");if(amount.signum()<=0)throw new IllegalArgumentException("立减金额必须大于0");c.setAmount(amount);c.setThreshold(BigDecimal.ZERO);}else{BigDecimal d=bd(b,"discount");if(d.compareTo(new BigDecimal("0.1"))<0||d.compareTo(new BigDecimal("9.9"))>0)throw new IllegalArgumentException("折扣必须在0.1至9.9之间");c.setDiscount(d);c.setCap(bdNullable(b,"cap"));}if("range".equals(c.getValidMode())&&(c.getValidStart()==null||c.getValidEnd()==null||!c.getValidEnd().isAfter(c.getValidStart())))throw new IllegalArgumentException("固定有效期不合法");if("after".equals(c.getValidMode())&&n(c.getValidDays())<=0)throw new IllegalArgumentException("有效天数必须大于0");refreshStatus(c);}
  public void refreshStatus(Coupon c){if(Boolean.TRUE.equals(c.getStopped())){c.setStatus("已停用");return;}LocalDateTime now=LocalDateTime.now(ZONE);if(c.getGrantStart()!=null&&now.isBefore(c.getGrantStart())){c.setStatus("未开始");return;}if("range".equals(c.getValidMode())&&c.getValidEnd()!=null&&!now.isBefore(c.getValidEnd())){c.setStatus("已结束");return;}c.setStatus("进行中");}
  private void syncStatuses(){List<Coupon> all=coupons.findAll();all.forEach(this::refreshStatus);coupons.saveAll(all);}
  public Map<String,Object> view(Coupon c){refreshStatus(c);Map<String,Object> m=new LinkedHashMap<>();m.put("id",c.getId());m.put("couponNo",c.getCouponNo());m.put("name",StringUtils.hasText(c.getName())?c.getName():c.getTitle());m.put("type",c.getType());m.put("amount",c.getAmount());m.put("threshold",c.getThreshold()!=null?c.getThreshold():c.getMinSpend());m.put("discount",c.getDiscount());m.put("cap",c.getCap());m.put("target",c.getTarget());m.put("scope",c.getScope());m.put("assignUsers",StringUtils.hasText(c.getAssignUsers())?JSON.parseArray(c.getAssignUsers()):List.of());m.put("total",c.getTotal());m.put("claimed",claims.countByCouponId(c.getId()));m.put("used",claims.countByCouponIdAndStatus(c.getId(),"USED"));m.put("grantMode",c.getGrantMode());m.put("grantStart",c.getGrantStart());m.put("validMode",c.getValidMode());m.put("validStart",c.getValidStart());m.put("validEnd",c.getValidEnd());m.put("validDays",c.getValidDays());m.put("status",c.getStatus());m.put("description",c.getDescription());m.put("createTime",c.getTimestamp());m.put("limit",c.getLimitPerUser());return m;}
  private String s(Map<String,Object>b,String k){Object v=b.get(k);return v==null?null:String.valueOf(v);}private int i(Map<String,Object>b,String k){return i0(b,k);}private int i0(Map<String,Object>b,String k){try{return b.get(k)==null?0:Integer.parseInt(String.valueOf(b.get(k)));}catch(Exception e){throw new IllegalArgumentException(k+" 必须是整数");}}private int n(Integer v){return v==null?0:v;}private BigDecimal bd(Map<String,Object>b,String k){BigDecimal x=bdNullable(b,k);return x==null?BigDecimal.ZERO:x;}private BigDecimal bdNullable(Map<String,Object>b,String k){try{return b.get(k)==null?null:new BigDecimal(String.valueOf(b.get(k)));}catch(Exception e){throw new IllegalArgumentException(k+" 必须是数字");}}private LocalDateTime dt(Object v){if(v==null||String.valueOf(v).isBlank())return null;String x=String.valueOf(v).replace('T',' ');try{return LocalDateTime.parse(x,DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));}catch(Exception e){try{return LocalDate.parse(x).atStartOfDay();}catch(Exception z){throw new IllegalArgumentException("时间格式必须为 yyyy-MM-dd HH:mm:ss");}}}private String blank(String s){return StringUtils.hasText(s)?s.trim():null;}private List<String> arr(Object v){if(v==null)return List.of();if(v instanceof Collection<?> c)return c.stream().map(String::valueOf).distinct().toList();return Arrays.stream(String.valueOf(v).split("[,，\\s]+" )).filter(StringUtils::hasText).distinct().toList();}private Long parseId(String s){try{return Long.valueOf(s);}catch(Exception e){return -1L;}}
}
